models.css:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Arabic:wght@400;600;700;800;900&family=Inter:wght@300;400;500;600;700;800;900&display=swap');
.card{font-family:'Noto Sans Arabic',sans-serif;text-align:center;direction:rtl;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;position:relative;min-height:100%}
.replay-button{display:inline-flex;align-items:center;justify-content:center;border-radius:50%;margin:8px auto;cursor:pointer;line-height:1;text-decoration:none}
:root{--bg:#f2f1ee;--card:#ffffff;--border:#0a0a0a;--text:#0a0a0a;--accent:#e63312;--glow:rgba(230,51,18,.14);--wfont:'Helvetica Neue',Arial,'Segoe UI',sans-serif;--afont:'Noto Naskh Arabic','Amiri',Tahoma,sans-serif;--rad:2px;}
*{box-sizing:border-box}
html,body{width:100%;height:100%;margin:0;padding:0}
body{overflow:hidden;-webkit-text-size-adjust:100%}
.scene{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:var(--bg);direction:ltr}
.fx{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:1}
.fx .sh{position:absolute;pointer-events:none;will-change:transform}
.frame{position:relative;z-index:2;width:min(92vw,820px);height:min(68vh,560px);display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--card);border:1.5px solid var(--border);border-radius:var(--rad,26px);box-shadow:0 24px 70px rgba(0,0,0,.4),0 0 60px var(--glow);overflow:hidden;animation:kf-pop .55s cubic-bezier(.18,1.3,.4,1) both}
@keyframes kf-pop{from{transform:scale(.9) translateY(14px);opacity:0}to{transform:none;opacity:1}}
@keyframes kf-spin-slow{to{transform:rotate(360deg)}}
@keyframes kf-sheen{0%,100%{transform:translateX(-30%)}50%{transform:translateX(30%)}}
@keyframes kf-drift-a{0%{transform:translate(0,0) scale(1)}100%{transform:translate(60px,40px) scale(1.18)}}
@keyframes kf-drift-b{0%{transform:translate(0,0) scale(1.1)}100%{transform:translate(-50px,-30px) scale(.95)}}
@keyframes kf-drift-c{0%{transform:translate(0,0) scale(.95)}100%{transform:translate(-40px,50px) scale(1.15)}}
.mid{flex:1;min-height:0;width:100%;display:flex;flex-direction:column;align-items:center;padding:clamp(14px,3.5vh,30px) clamp(14px,4vw,56px) clamp(4px,1.2vh,10px)}
.slot{width:100%;flex:1;min-height:0;display:flex;align-items:center;justify-content:center;overflow:hidden}
.fitme{display:inline-block;white-space:nowrap;max-width:none;text-align:center;line-height:1.06;font-weight:800;transform-origin:center}
.word{font-family:var(--wfont);color:var(--text);font-size:76px;text-shadow:0 4px 26px var(--glow)}
.trans{font-family:var(--afont);color:var(--accent);font-size:50px;direction:rtl;text-shadow:0 3px 18px var(--glow)}
.divider{width:min(34%,230px);height:3px;border-radius:2px;background:linear-gradient(90deg,transparent,var(--accent),transparent);opacity:.6;box-shadow:0 0 14px var(--glow);flex:0 0 auto;margin:2px 0}
.sound{position:relative;z-index:3;padding-bottom:clamp(12px,2.6vh,22px);flex:0 0 auto}
.replay-button{display:inline-flex;align-items:center;justify-content:center;cursor:pointer;padding:0;margin:0;outline:none;border:none;background:none;position:relative;z-index:2;-webkit-tap-highlight-color:transparent;transition:transform .16s ease;appearance:none;-webkit-appearance:none}
.replay-button:active{transform:scale(.9)}
.replay-button svg{position:relative;z-index:2}

.fx{background:repeating-linear-gradient(90deg,transparent 0 79px,rgba(10,10,10,.055) 79px 80px),repeating-linear-gradient(0deg,transparent 0 79px,rgba(10,10,10,.055) 79px 80px)}
.sh-red{top:0;left:0;width:38%;height:14px;background:#e63312}
.sh-black{bottom:0;right:0;width:26%;height:10px;background:#0a0a0a}
.sh-h{top:50%;left:0;right:0;height:1px;background:rgba(10,10,10,.12)}
.sh-v{left:50%;top:0;bottom:0;width:1px;background:rgba(10,10,10,.12)}

.word{text-transform:uppercase;letter-spacing:2px;font-weight:900;color:#0a0a0a;text-shadow:none}
.trans{color:#e63312}

.frame{box-shadow:10px 10px 0 rgba(10,10,10,.12)}
.replay-button{width:52px;height:52px;background:#e63312;border-radius:0}
.replay-button svg{display:none}
.replay-button::before{content:"";width:0;height:0;border-left:18px solid #fff;border-top:11px solid transparent;border-bottom:11px solid transparent;margin-left:4px}
.replay-button:hover{background:#0a0a0a}

/* fixed */
.sound{display:flex;align-items:center;justify-content:center;gap:16px}

/* ===== توحيد حاوية الصوت ===== */
.sound,[class$="-sound"]{position:relative;z-index:6;flex:0 0 auto;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:8px;width:100%;box-sizing:border-box;padding-bottom:clamp(10px,2.2vh,18px);margin:0;height:auto;min-height:0;border-radius:0;background:transparent;border:none;box-shadow:none}
.sndbar{display:flex;align-items:center;justify-content:center;gap:9px;flex-wrap:nowrap;width:100%;position:relative}
.sndbtn{width:38px;height:38px;border-radius:50%;background:rgba(127,127,127,.16);border:2px solid var(--text,#101010);color:var(--text,#101010);font-family:'Segoe UI',var(--wfont),sans-serif;font-weight:800;font-size:11.5px;letter-spacing:.5px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;outline:none;-webkit-tap-highlight-color:transparent;user-select:none;opacity:.96;transition:transform .15s ease,opacity .15s ease,background .15s ease;padding:0;line-height:1;box-sizing:border-box;box-shadow:0 1px 5px rgba(0,0,0,.16)}
.sndbtn:hover{opacity:1;background:rgba(127,127,127,.3)}
.sndbtn:active{transform:scale(.86)}
.sndbtn .ic{pointer-events:none}
.sndbtn.snd-both{font-size:16px;letter-spacing:0}
.sndbtn.snd-play{width:46px;height:46px;background:var(--accent,#e63312);border-color:var(--accent,#e63312);color:#fff;opacity:1}
.sndbtn.snd-play:hover{background:var(--accent,#e63312);filter:brightness(1.1)}
.play-tri{width:0;height:0;border-left:14px solid #fff;border-top:8px solid transparent;border-bottom:8px solid transparent;margin-left:4px}





/* ===== مؤقّت البطاقة — أصغر ===== */
#aintimer{position:fixed!important;top:9px!important;right:13px!important;z-index:2147483000!important;direction:ltr!important;display:inline-block!important;font-family:'SF Mono','Consolas','Menlo',monospace!important;font-size:10px!important;font-weight:500!important;font-variant-numeric:tabular-nums!important;letter-spacing:.8px!important;color:rgba(226,232,240,.68)!important;background:rgba(15,23,42,.22)!important;-webkit-backdrop-filter:blur(6px)!important;backdrop-filter:blur(6px)!important;border:1px solid rgba(148,163,184,.13)!important;border-radius:7px!important;padding:2px 7px 3px!important;line-height:1!important;box-shadow:0 2px 8px rgba(2,6,23,.08)!important;user-select:none!important;pointer-events:none!important;opacity:.68!important}

@keyframes aiTimerIn{from{opacity:0;transform:translateY(-3px)}to{opacity:.68;transform:none}}to{opacity:.78;transform:none}}



/* ===== إيقاف كل الحركة: الشكل فقط ===== */
*{animation:none!important}

/* ===== أيقونة نوع الكلمة — صغيرة وغير مهمة (انكليزي تاسع) ===== */
.pos-ico{position:fixed!important;top:10px!important;left:12px!important;z-index:2147483000!important;direction:ltr!important;font-family:'Inter','Segoe UI',sans-serif!important;font-size:8.5px!important;font-weight:600!important;letter-spacing:.4px!important;color:rgba(120,120,125,.6)!important;background:rgba(127,127,127,.10)!important;border:1px solid rgba(127,127,127,.18)!important;border-radius:4px!important;padding:1px 5px 2px!important;line-height:1!important;user-select:none!important;pointer-events:none!important;opacity:.7!important;box-shadow:none!important}

.pos-ico { display: none !important; }


.sndbtn:active { transform: scale(0.84) !important; transition: transform 0.1s ease !important; }
.sndbtn { transition: transform 0.15s ease, background 0.15s ease !important; }

.fitme,.word,.trans{overflow-wrap:normal !important;word-break:keep-all !important;hyphens:none !important}
.fit-token{display:inline-block !important;white-space:nowrap !important;overflow-wrap:normal !important;word-break:keep-all !important;hyphens:none !important}

/* UI stability fixes */
.sh{display:none !important}
.fitme{overflow-wrap:anywhere !important}

